from collections import Counter
import math


def task_func(nested_dict):
    """Sum values by key, remove 'ele', and take the sine of each sum."""
    totals = Counter()
    for inner_dict in nested_dict.values():
        totals.update(inner_dict)
    totals.pop('ele', None)
    return {key: math.sin(value) for key, value in totals.items()}

