import random
import string

POSSIBLE_LETTERS = ['a', 'b', 'c']


def task_func(word):
    """Return random adjacent pairs, rejecting non-ASCII-letter characters."""
    if any(letter not in string.ascii_letters for letter in word):
        raise ValueError('Input must only contain letters.')

    if len(word) < 2:
        return ['' for _ in POSSIBLE_LETTERS]

    return [
        word[index:index + 2]
        for index in (
            random.randrange(len(word) - 1) for _ in POSSIBLE_LETTERS
        )
    ]

