from collections import defaultdict
from random import randint


def task_func(dict1):
    """Return salary lists for departments whose codes start with 'EMP$$'.

    Salaries are random integers from 30,000 through 100,000 inclusive
    (the specification does not prescribe a salary range).
    """
    employee_data = defaultdict(list)
    for department, count in dict1.items():
        if department.startswith('EMP$$'):
            employee_data[department] = [randint(30000, 100000) for _ in range(count)]
    return dict(employee_data)

